int x = 5;
int result = x++ + ++x;
System.out.println("x = " + x);         // 7
System.out.println("result = " + result); // 12
// x++ zwraca 5 (x staje sie 6), ++x zwraca 7 (x staje sie 7 PRZED zwroceniem) -> 5 + 7 = 12";

boolean a = true, b = false, c = true;
boolean wynik = (a && b) || (!b && c) && !(a && !c);
System.out.println(wynik);
// (a && b) = (true && false) = false
// (!b && c) = (true && true) = true
// !(a && !c) = !(true && false) = !(false) = true
// (true && true) = true (bo && ma wyzszy priorytet niz ||)
// false || true = true

